mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("n=5 updates=(1,3,3),(2,4,2)","0,3,5,5,2"),
        ("n=4 updates=(0,1,2),(2,3,1)","2,2,1,1"),
        ("n=4 updates=(0,3,1),(0,0,2)","3,1,1,1"),
        ("n=5 updates=(1,1,7),(1,3,-2)","0,5,-2,-2,0"),
        ("n=3 updates=(0,0,1),(2,2,1)","1,0,1"),
        ("  \nn=5 updates=(1,3,3),(2,4,2)\n  ","0,3,5,5,2"),
        ("\nn=3 updates=(0,0,1),(2,2,1)\n","1,0,1")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS difference-array");
}
